import React, { useState, useEffect } from 'react';
import { api } from '../api';

const ProductModal = ({ isOpen, onClose, onSubmit, initialData }) => {
    const [file, setFile] = useState(null);
    const [formData, setFormData] = useState({
        title: '', category: 'GPU', price: '', description: '', stock: '0', image: ''
    });

    useEffect(() => {
        if (initialData) {
            setFormData(initialData);
        } else {
            setFormData({ title: '', category: 'GPU', price: '', description: '', stock: '0', image: '' });
        }
        setFile(null); // Сбрасываем выбранный файл при открытии
    }, [initialData, isOpen]);

    if (!isOpen) return null;

    const handleFormSubmit = async (e) => {
        e.preventDefault();
        let finalImageUrl = formData.image;

        if (file) {
            try {
                // Сначала отправляем файл на сервер и получаем его новый путь
                finalImageUrl = await api.uploadImage(file);
            } catch (err) {
                console.error("Ошибка загрузки:", err);
                alert("Не удалось загрузить фото. Проверьте, запущен ли бэкенд и установлена ли библиотека multer.");
                return; 
            }
        }
        // Отправляем все данные формы (включая цену и путь к фото) в App.js
        onSubmit({ ...formData, image: finalImageUrl });
    };

    return (
        <div className="modal-overlay" onClick={onClose}>
            <div className="modal-content" onClick={e => e.stopPropagation()}>
                <h2>{initialData ? 'Редактировать товар' : 'Добавить новый товар'}</h2>
                <form onSubmit={handleFormSubmit}>
                    <div className="form-group">
                        <label>Название</label>
                        <input 
                            type="text" required value={formData.title} 
                            onChange={e => setFormData({...formData, title: e.target.value})} 
                        />
                    </div>
                    
                    <div className="form-row" style={{ display: 'flex', gap: '10px' }}>
                        <div className="form-group" style={{ flex: 1 }}>
                            <label>Цена (₽)</label>
                            <input 
                                type="number" required value={formData.price} 
                                onChange={e => setFormData({...formData, price: e.target.value})} 
                            />
                        </div>
                        <div className="form-group" style={{ flex: 1 }}>
                            <label>Категория</label>
                            <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                                <option value="GPU">GPU</option>
                                <option value="CPU">CPU</option>
                                <option value="RAM">RAM</option>
                                <option value="SSD">SSD</option>
                            </select>
                        </div>
                    </div>

                    <div className="form-group">
                        <label>Описание</label>
                        <textarea 
                            required rows="3" value={formData.description} 
                            onChange={e => setFormData({...formData, description: e.target.value})}
                        />
                    </div>

                    <div className="form-group">
                        <label>Загрузить фото</label>
                        <input type="file" accept="image/*" onChange={e => setFile(e.target.files[0])} />
                    </div>

                    <div className="modal-actions">
                        <button type="button" onClick={onClose}>Отмена</button>
                        <button type="submit" className="save-btn">Сохранить</button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default ProductModal;
